package com.EOT.project.controller;
import com.EOT.project.dto.request.PostReportRequestDTO; import com.EOT.project.model.UserModel; import com.EOT.project.service.*; import java.util.*; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class PostReportControllerTest { @Mock PostReportService service; @Mock CurrentUserService current; @InjectMocks PostReportController controller;
 @Test void obtainsProfileBeforeCreatingReport() { var auth=new UsernamePasswordAuthenticationToken("auth","x"); var profile=UserModel.builder().userId(UUID.randomUUID()).build(); when(current.requireProfile(auth)).thenReturn(profile); controller.report(UUID.randomUUID(),new PostReportRequestDTO("spam"),auth); verify(service).create(any(),same(profile),any()); } }
